plugins {
    id 'application'
    id 'java-library'
    id "io.freefair.aspectj" version "8.13" //same as gradle version!
}
compileJava { options.encoding = "UTF-8" }
compileTestJava { options.encoding = "UTF-8" }

// Uncomment the below lines to make UTF-9 non default while testing
//allprojects {
//    tasks.withType(Test) {
//        systemProperty "file.encoding", "US-ASCII"
//    }
//}

java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(21))
    }
}

version = "12.5.0"

repositories {
    mavenCentral()

    maven { url = 'https://build.shibboleth.net/nexus/content/repositories/releases/' }
}

dependencies {

    // https://mvnrepository.com/artifact/com.google.code.gson/gson
    // if this changes, remember to also change in the ee folder's build.gradle
    implementation group: 'com.google.code.gson', name: 'gson', version: '2.13.1'

    // https://mvnrepository.com/artifact/com.fasterxml.jackson.dataformat/jackson-dataformat-yaml
    implementation group: 'com.fasterxml.jackson.dataformat', name: 'jackson-dataformat-yaml', version: '2.22.1'

    // https://mvnrepository.com/artifact/com.fasterxml.jackson.dataformat/jackson-dataformat-cbor
    implementation group: 'com.fasterxml.jackson.dataformat', name: 'jackson-dataformat-cbor', version: '2.22.1'

    // https://mvnrepository.com/artifact/com.fasterxml.jackson.core/jackson-core
    implementation group: 'com.fasterxml.jackson.core', name: 'jackson-databind', version: '2.22.1'

    // https://mvnrepository.com/artifact/org.apache.tomcat.embed/tomcat-embed-core
    api group: 'org.apache.tomcat.embed', name: 'tomcat-embed-core', version: '11.0.25'

    // https://mvnrepository.com/artifact/com.google.code.findbugs/jsr305
    implementation group: 'com.google.code.findbugs', name: 'jsr305', version: '3.0.2'

    // https://mvnrepository.com/artifact/org.xerial/sqlite-jdbc
    implementation group: 'org.xerial', name: 'sqlite-jdbc', version: '3.45.1.0'

    // https://mvnrepository.com/artifact/org.mindrot/jbcrypt
    implementation group: 'org.mindrot', name: 'jbcrypt', version: '0.4'

    // https://mvnrepository.com/artifact/org.jetbrains/annotations
    implementation group: 'org.jetbrains', name: 'annotations', version: '13.0'

    // https://mvnrepository.com/artifact/de.mkammerer/argon2-jvm
    implementation group: 'de.mkammerer', name: 'argon2-jvm', version: '2.11'

    // https://mvnrepository.com/artifact/com.auth0/java-jwt
    implementation 'com.auth0:java-jwt:4.4.0'

    // https://mvnrepository.com/artifact/com.lambdaworks/scrypt
    implementation group: 'com.lambdaworks', name: 'scrypt', version: '1.4.0'

    // https://mvnrepository.com/artifact/com.eatthepath/java-otp
    implementation group: 'com.eatthepath', name: 'java-otp', version: '0.4.0'

    // https://mvnrepository.com/artifact/commons-codec/commons-codec
    implementation group: 'commons-codec', name: 'commons-codec', version: '1.15'

    // https://mvnrepository.com/artifact/com.googlecode.libphonenumber/libphonenumber/
    implementation group: 'com.googlecode.libphonenumber', name: 'libphonenumber', version: '8.13.25'

    // https://mvnrepository.com/artifact/com.webauthn4j/webauthn4j-core
    implementation group: 'com.webauthn4j', name: 'webauthn4j-core', version: '0.28.6.RELEASE'

    implementation platform("io.opentelemetry.instrumentation:opentelemetry-instrumentation-bom-alpha:2.29.0-alpha")
    //alpha because of jmx-metrics collector

    // Open SAML
    implementation group: 'org.opensaml', name: 'opensaml-core-api', version: '5.2.3'
    implementation group: 'org.opensaml', name: 'opensaml-core-impl', version: '5.2.3'
    implementation group: 'org.opensaml', name: 'opensaml-saml-impl', version: '5.2.3'
    implementation group: 'org.opensaml', name: 'opensaml-security-impl', version: '5.2.3'
    implementation group: 'org.opensaml', name: 'opensaml-xmlsec-impl', version: '5.2.3'

    implementation("ch.qos.logback:logback-core:1.5.38")
    implementation("ch.qos.logback:logback-classic:1.5.38")

    // OpenTelemetry core
    implementation("io.opentelemetry:opentelemetry-sdk")
    implementation("io.opentelemetry:opentelemetry-exporter-otlp")
    implementation("io.opentelemetry:opentelemetry-exporter-logging")
    implementation("io.opentelemetry:opentelemetry-api")

    implementation("io.opentelemetry.semconv:opentelemetry-semconv")

    implementation('org.aspectj:aspectjrt:1.9.24')

    constraints {
        // velocity-engine-core 2.4.1 (via opensaml-saml-impl) pins 3.17.0, which is
        // affected by CVE-2025-48924 (uncontrolled recursion); fixed in 3.18.0
        implementation 'org.apache.commons:commons-lang3:3.20.0'

        // opensaml 5.2.3 pulls httpclient5 5.3.1 / httpcore5 5.2.x, affected by
        // CVE-2026-64607 (connection leak on invalid Content-Encoding; fixed in 5.6.3),
        // CVE-2026-54399 (HTTP/1.1 parser memory exhaustion; fixed in 5.4.3) and
        // CVE-2026-54428 (HPACK decoder memory exhaustion; fixed in 5.4.3).
        // httpclient5 5.6.4 is built against httpcore5 5.4.3.
        implementation 'org.apache.httpcomponents.client5:httpclient5:5.6.4'
        implementation 'org.apache.httpcomponents.client5:httpclient5-cache:5.6.4'
        implementation 'org.apache.httpcomponents.core5:httpcore5:5.4.3'
        implementation 'org.apache.httpcomponents.core5:httpcore5-h2:5.4.3'

        // bcprov-jdk18on 1.84 (transitive via webauthn4j-core / opensaml) is affected by
        // CVE-2026-8763 (Bouncy Castle Name Constraints bypass in X.509 path validation);
        // fixed in 1.85. Surfaced by the container security scan of supertokens-postgresql.
        implementation 'org.bouncycastle:bcprov-jdk18on:1.85'
    }

    compileOnly project(":supertokens-plugin-interface")

    // this is so that we can find plugin-interface jar while testing
    testImplementation project(":supertokens-plugin-interface")

    testImplementation 'junit:junit:4.12'

    // https://mvnrepository.com/artifact/org.mockito/mockito-core
    testImplementation group: 'org.mockito', name: 'mockito-core', version: '3.1.0'

    // https://mvnrepository.com/artifact/org.reflections/reflections
    testImplementation group: 'org.reflections', name: 'reflections', version: '0.9.10'

    testImplementation 'com.tngtech.archunit:archunit-junit4:1.4.1'

    // https://mvnrepository.com/artifact/com.webauthn4j/webauthn4j-test
    testImplementation group: 'com.webauthn4j', name: 'webauthn4j-test', version: '0.28.6.RELEASE'

    // Pulls in PostgreSQLTestDatabaseHelper via ServiceLoader so that core tests can create
    // per-worker databases without importing org.postgresql directly into supertokens-core.
    // findProject() returns null (instead of throwing) when the plugin isn't checked out (e.g. sqlite CI job).
    if (findProject(':supertokens-postgresql-plugin') != null) {
        testImplementation(testFixtures(project(':supertokens-postgresql-plugin')))
    }
}
application {
    mainClass.set("io.supertokens.Main")
}

jar {
    archiveBaseName.set('core')
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}


tasks.register('copyJars', Copy) {
    from configurations.runtimeClasspath
    into layout.buildDirectory.dir("dependencies")
}

test {
    jvmArgs = ['-Djava.security.egd=file:/dev/urandom',
               "--add-opens=java.base/java.lang=ALL-UNNAMED",
               "--add-opens=java.base/java.util=ALL-UNNAMED",
               "--add-opens=java.base/java.util.concurrent=ALL-UNNAMED"]
    // Only forward OAuth vars when all three are explicitly set.  Using getOrDefault
    // with fallback values would trigger useExternalOAuth=true in TestServiceUtils even
    // when no external Hydra is available, causing all test JVMs to crash on startup.
    def _oauthHost       = System.getenv('TEST_OAUTH_HOST')
    def _oauthPublicPort = System.getenv('TEST_OAUTH_PUBLIC_PORT')
    def _oauthAdminPort  = System.getenv('TEST_OAUTH_ADMIN_PORT')
    if (_oauthHost != null && _oauthPublicPort != null && _oauthAdminPort != null) {
        environment 'TEST_OAUTH_HOST',        _oauthHost
        environment 'TEST_OAUTH_PUBLIC_PORT', _oauthPublicPort
        environment 'TEST_OAUTH_ADMIN_PORT',  _oauthAdminPort
    }
    testLogging {
        outputs.upToDateWhen { false }
        showStandardStreams = true
    }
    maxParallelForks = Runtime.runtime.availableProcessors()
}

import org.gradle.api.tasks.testing.logging.TestExceptionFormat
import org.gradle.api.tasks.testing.logging.TestLogEvent

tasks.withType(Test).configureEach {
    testLogging {
        // set options for log level LIFECYCLE
        events = [TestLogEvent.FAILED,
                TestLogEvent.PASSED,
                TestLogEvent.SKIPPED,
                TestLogEvent.STANDARD_OUT]
        exceptionFormat = TestExceptionFormat.FULL
        showExceptions = true
        showCauses = true
        showStackTraces = true

        // set options for log level DEBUG and INFO
        debug {
            events = [TestLogEvent.STARTED,
                    TestLogEvent.FAILED,
                    TestLogEvent.PASSED,
                    TestLogEvent.SKIPPED,
                    TestLogEvent.STANDARD_ERROR,
                    TestLogEvent.STANDARD_OUT]
            exceptionFormat = TestExceptionFormat.FULL
        }

